#include<bits/stdc++.h>
using namespace std;
class PhanSo{
	private:
		int ts;
		int ms;
	public:
		PhanSo(){
			this->ts = 0;
			this->ms = 1;
		}
		PhanSo(int ts,int ms){
			this->ts = ts;
			this->ms = ms;
		}
		void RutGon(){
			this->ts = this->ts / gcd(this->ts,this->ms);
			this->.ms = this->ms / gcd(this->ts,this->ms);
		}
		bool operator == (PhanSo &ps1, PhanSo &ps2){
			return ps1.ts == ps2.ts && ps1.ms == ps2.ms;
		}
		friend istream &operator >> (istream & is, PhanSo & t){
			cout<<"Nhap phan so: ";
			is>>t.ts>>t.ms;
			return is;
		} 
};
int main(){
	PhanSo ps1(3,4);
	ps1.RutGon();
	PhanSo ps2;
	cin<<ps2;
	ps2.RutGon();
	if(ps1 == ps2){
		cout<<"Bang nhau";
	}else{
		cout<<"Khong bang nhau";
	}
	return 0;
}

